// Ajuste aqui o subdomínio da sua conta Kommo
const KOMMO_BASE_URL = 'https://amarketingevendas.kommo.com';
// 143 = etapa "Venda perdida" (fixa em todo funil do Kommo)
const STATUS_PERDIDO = '143';

// O Kommo manda x-www-form-urlencoded (ex.: leads[status][0][id]=123).
// Se o n8n entregar as chaves "achatadas", reconstruímos o objeto.
function unflatten(flat) {
  const out = {};
  for (const [key, value] of Object.entries(flat)) {
    const parts = key.replace(/\]/g, '').split('[');
    let cur = out;
    parts.forEach((p, i) => {
      if (i === parts.length - 1) cur[p] = value;
      else cur = cur[p] = cur[p] ?? {};
    });
  }
  return out;
}

const toArray = (x) => Array.isArray(x) ? x : (x && typeof x === 'object' ? Object.values(x) : []);

const seen = new Set();
const result = [];

for (const item of $input.all()) {
  let body = item.json.body ?? item.json;
  if (Object.keys(body).some((k) => k.includes('['))) body = unflatten(body);

  const leads = body.leads ?? {};
  // Mudança de etapa chega em leads.status; edições gerais em leads.update
  const candidatos = [...toArray(leads.status), ...toArray(leads.update)];

  for (const lead of candidatos) {
    if (String(lead.status_id) !== STATUS_PERDIDO) continue;
    const id = Number(lead.id);
    if (!id || seen.has(id)) continue;
    seen.add(id);
    result.push({ json: { lead_id: id, base_url: KOMMO_BASE_URL } });
  }
}

// Lista vazia = nenhum lead perdido neste evento; o fluxo para aqui.
return result;

// Cruza cada lead perdido com cada bot da conta
const leads = $('Extrair leads perdidos').all();
const bots = $input.first().json._embedded?.bots ?? [];

const out = [];
for (const lead of leads) {
  for (const bot of bots) {
    out.push({
      json: {
        lead_id: lead.json.lead_id,
        bot_id: bot.id,
        bot_name: bot.name ?? null,
        base_url: lead.json.base_url,
      },
    });
  }
}
return out;
